import sys

def findMaximumNum(s, k):
    def solve(current_s, remaining_k, index):
        if remaining_k == 0 or index >= len(current_s):
            return current_s

        max_char = current_s[index]
        max_pos = index

        for i in range(index + 1, len(current_s)):
            if current_s[i] > max_char:
                max_char = current_s[i]
                max_pos = i

        if max_pos == index:
            return solve(current_s, remaining_k, index + 1)

        best_result = ""
        new_s = list(current_s)
        new_s[index], new_s[max_pos] = new_s[max_pos], new_s[index]
        best_result = solve("".join(new_s), remaining_k - 1, index + 1)

        for i in range(index + 1, len(current_s)):
                if current_s[i] == max_char and i != max_pos:
                    temp_s = list(current_s)
                    temp_s[index], temp_s[i] = temp_s[i], temp_s[index]
                    candidate = solve("".join(temp_s), remaining_k - 1, index + 1)
                    if candidate > best_result:
                        best_result = candidate

        return best_result

    return solve(s, k, 0)

if __name__ == "__main__":
    line1 = sys.stdin.readline().strip()
    line2 = sys.stdin.readline().strip()
    if line1 and line2:
        k = int(line1)
        s = line2
        result = findMaximumNum(s, k)
        print(result)
    elif line1:
        k = int(line1)
